// Box art for Panel Pop (meta/box_art.png), drawn by the game's own runtime like scripts/make-cart-art.mjs, with a
// layout of its own (the logo's letter panels on the light sky, Pip and the rivals) that the generic cover does not make. The screenshot and logo
// still come from make-cart-art.mjs.
// usage: node scripts/make-panel-pop-art.mjs        (needs build/gs and carts/panel-pop generated by make-panel-pop.mjs)
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { png, decodeBmp } from "./png.mjs";
import { writePictureCart } from "./picture-cart.mjs";

const dir = "carts/panel-pop";
const tmp = mkdtempSync(join(tmpdir(), "gs-box-"));
mkdirSync(join(tmp, "sprites"));
mkdirSync(join(tmp, "tilesets"));
const sprites = ["spr_panels", "spr_logo", "spr_char_pip", "spr_char_bloop", "spr_char_kit", "spr_char_ember", "spr_char_frost", "spr_font_w"];
for (const s of sprites) copyFileSync(join(dir, "sprites", s + ".png"), join(tmp, "sprites", s + ".png"));
copyFileSync(join(dir, "tilesets", "ts_sky.png"), join(tmp, "tilesets", "ts_sky.png"));
const body = `
  local sky = gs.image("tilesets/ts_sky.png")
  for y = 0, H, 64 do for x = 0, W, 64 do gs.tile(sky, 0, 0, 64, 64, x, y) end end
  local logo, panels = img("spr_logo"), img("spr_panels")
  -- a scatter of panels behind
  local spots = { {14, 10, 0}, {196, 22, 3}, {30, 150, 4}, {200, 176, 1}, {10, 262, 2}, {20, 206, 5}, {118, 8, 2} }
  for _, s in ipairs(spots) do gs.tile(panels, s[3] * 6 * 16, 0, 16, 16, s[1], s[2], 2) end
  -- PANEL over POP, one letter a panel
  local word1, word2 = { 0, 1, 2, 3, 4 }, { 0, 5, 0 }
  for i, f in ipairs(word1) do gs.tile(logo, f * 32, 0, 32, 32, 30 + (i - 1) * 36, 56 + (i % 2) * 4) end
  for i, f in ipairs(word2) do gs.tile(logo, f * 32, 0, 32, 32, 66 + (i - 1) * 36, 100 + (i % 2) * 4) end
  gs.tile(img("spr_char_pip"), 64, 0, 32, 32, 72, 168, 3)
  local cast = { { "spr_char_bloop", 8, 252 }, { "spr_char_ember", 64, 266 }, { "spr_char_frost", 136, 266 }, { "spr_char_kit", 192, 252 } }
  for _, c in ipairs(cast) do gs.tile(img(c[1]), 0, 0, 32, 32, c[2], c[3], 1.25) end
  local font = img("spr_font_w")
  local s = "GAMESTUDIO"
  for i = 1, #s do gs.tile(font, (s:byte(i) - 32) * 8, 0, 8, 8, 80 + (i - 1) * 8, 308) end
`;
writePictureCart(tmp, 240, 320, body, `local function img(n) return gs.image("sprites/" .. n .. ".png") end`);
const bmp = join(tmp, "frame.bmp");
const r = spawnSync("build/gs", [tmp], { encoding: "utf8", env: { ...process.env, GS_SAVE_DIR: mkdtempSync(join(tmpdir(), "gs-save-")), SDL_VIDEODRIVER: "dummy", SDL_AUDIODRIVER: "dummy", GS_MAX_FRAMES: "3", GS_DUMP_FRAME: bmp } });
if (r.status !== 0) { console.error(r.stdout, r.stderr); process.exit(1); }
const f = decodeBmp(readFileSync(bmp));
writeFileSync(join(dir, "meta/box_art.png"), png(f.width, f.height, f.data));
console.log("wrote carts/panel-pop/meta/box_art.png");
